export default meta
type S = StoryObj<typeof InfoTip>
export const Обычная: S = { args: { data: { title: 'Групповой этап', rows: [['Команд', '10'], ['Даты', '05 – 08.10'], ['Формат', 'Bo2']], legend: [{ mark: 'up', text: 'В плей-офф' }, { mark: 'down', text: 'Выбывают' }] } } }
export const СПримечанием: S = { args: { data: { title: 'Статистика героев', rows: [['Карт', '48'], ['Героев', '96']], note: 'Пикрейт — пики и баны, % карт' } } }
`,DRe=`/** Кнопка «i» в шапке таблицы (24.11, лаба tour-chat-24 v13, дирижёр: «правило для всех таблиц»): значок на подложке 28, как «О турнире»;
 *  всегда самая правая в шапке, подписей рядом нет — всё в подсказке. Подсказка: заголовок, «подпись — значение» в две колонки,
 *  легенда (цвет зоны или значок — что значит), примечание. Подписи — одной колонкой по самой длинной, значения в одну строку. */
import type { ReactNode } from 'react'
import { Tooltip } from '@/atoms/Tooltip'
import { Icon } from '@/atoms/Icon'
import { PhIcon } from '@/engine/common/PageHeader/v5/icons'
import './InfoTip.css'

/** Что в подсказке: заголовок, факты «подпись — значение», легенда (цвет зоны или значок + что значит), примечание */
export type InfoTipData = { title: string; rows: [string, ReactNode][]; note?: string; legend?: { mark: 'up' | 'down' | 'mid' | 'shield' | 'ph-player' | 'swap'; text: string }[] }

const Mark = ({ m }: { m: NonNullable<InfoTipData['legend']>[number]['mark'] }) =>
  m === 'up' || m === 'down' || m === 'mid' ? <i className={'itip__sw itip__sw--' + m} /> : <span className={'itip__ic' + (m === 'swap' ? ' is-sw' : '')}><Icon name={m as 'shield'} size={12} /></span>

function Body({ d }: { d: InfoTipData }) {
  const legend = d.legend?.length ? <ul className="itip__lg">{d.legend.map((l) => <li key={l.text}><Mark m={l.mark} />{l.text}</li>)}</ul> : null
  return (
    <div className="itip"><b className="itip__h">{d.title}</b>
      <dl>{d.rows.map(([k, v]) => <div key={k}><dt>{k}</dt><dd>{v}</dd></div>)}</dl>{legend && <><hr />{legend}</>}{d.note && <><hr /><small className="itip__note">{d.note}</small></>}</div>)
}

/** «i» с подсказкой — в \`actions\` шапки виджета (Widget / TableWidget) или в конце заголовка, обёрнутого в \`.itip-hd\` */
export const InfoTip = ({ data }: { data: InfoTipData }) => (
  <Tooltip side="top" align="end" content={<Body d={data} />}>
    <button type="button" className="itip-btn" aria-label={data.title}><PhIcon name="info" size={15} /></button>
  </Tooltip>)
