export type RoleIconProps = { pos: 1 | 2 | 3 | 4 | 5; size?: number; /** Свой цвет; нет — цвет позиции */ color?: string; className?: string }

export function RoleIcon({ pos, size = 14, color, className }: RoleIconProps) {
  return <svg className={'role-icon' + (className ? ' ' + className : '')} width={size} height={size} viewBox="0 0 12 12" fill={color ?? ROLE_COLOR[pos]} aria-hidden="true" dangerouslySetInnerHTML={{ __html: P[pos] }} />
}
