export const statusArgTypes = {
  status: { control: 'inline-radio', options: ['ready', 'loading', 'error'], description: 'Состояние данных: ready — готово (вид как в лабе) · loading — заглушки по форме виджета · error — «Не удалось загрузить» и «Повторить»' },
  onRetry: { description: 'Нажали «Повторить» в состоянии error' },
} as const

export type StatusErrorProps = {
  onRetry?: () => void
  /** По центру всей высоты родителя */
  fill?: boolean
  /** В строку (шапки) */
  inline?: boolean
  /** Растянуться в колонке-флексе родителя (виджеты новостей) */
  grow?: boolean
}
/** Ошибка загрузки: «Не удалось загрузить» (атом EmptyState) + «Повторить» (Button secondary sm) */
