/* ---------- состояния и узкая колонка (дирижёр 17.11) ---------- */
export type StateArgs = { narrow?: boolean; status?: 'ready' | 'loading' | 'error'; empty?: boolean }
/** «Игроки» в нужном состоянии: загрузка · ошибка · нет данных · ничего не нашли (фильтр) */
