/** Общая шапка страницы движка v4 — v3 + плашка при прокрутке (лаба header-stick v19). Плашку видно на страницах: листни вниз. Было v2 — лаба sandbox-project/lab/engine-header (матч — v7, турнир — v21; дирижёр 20.11). Ширина главной колонки — 1040, фон страницы. */
const wrap = (St: ComponentType) => <div style={{ width: 1040, padding: 16, background: 'var(--w-page)' }}><St /></div>
const meta: Meta<typeof PageHeader> = { title: 'Движок/Общие/Шапка страницы/PageHeader v4', component: PageHeader, parameters: { layout: 'fullscreen' }, decorators: [wrap] }
