const meta: Meta<typeof StatCompare> = { title: 'Движок/Общие/Сравнение двух сторон/StatCompare v1', component: StatCompare, decorators: [(S) => <div style={{ width: 300, height: 340, display: 'flex', padding: 16, background: 'var(--w-surface)', borderRadius: 12 }}><S /></div>] }
