import { DB, img } from '@/data/db'

export type HS = { hero: string; picks: number; pickWins: number; bans: number; radiant: [number, number]; dire: [number, number]; pickBan: number }
export type HeroPlayer = { player: string; team: string; pos: number; maps: number; wins: number }
export type HeroTeam = { team: string; picks: number; bans: number }
export type Pos = { pos: number; maps: number; wins: number }
export type Matchup = { hero: string; d: number }
export type MetaRow = { hero: string; picks: number; wr: number; pb: number; bans: number }
export type HeroView = {
  id: string; name: string; img?: string
  attr: string; roles: string[]; complexity: number
  games: number
  s: HS | null
  wr: number; pickRate: number; banRate: number
  rank: { picks: number; wr: number; bans: number; pb: number; of: number }
  players: HeroPlayer[]
  teams: HeroTeam[]
  positions: Pos[]
  best: Matchup[]; worst: Matchup[]
  /** v5–v7: противостояния со всеми частыми героями TI — сдвиг винрейта в игре (d) и на линии к 10-й минуте (lane), ‼️ пример */
  matchups: (Matchup & { lane: number; games: number })[]
  patches: { p: string; wr: number; pick: number }[]
  meta: MetaRow[]
}

type PS = { player: string; maps: number; wins: number; heroes: { hero: string; maps: number; wins: number }[] }
const pct = (w: number, n: number) => (n ? Math.round((w / n) * 100) : 0)
/** Пример: детерминированный «шум» от имени героя — чтобы у разных героев были разные, но стабильные числа */
const seed = (s: string) => { let h = 2166136261; for (const c of s) h = Math.imul(h ^ c.charCodeAt(0), 16777619); return () => ((h = Math.imul(h ^ (h >>> 15), 2246822507) ^ Math.imul(h ^ (h >>> 13), 3266489909)) >>> 0) / 4294967296 }
const EX: Record<string, { attr: string; roles: string[]; complexity: number }> = {
  earth_spirit: { attr: 'Сила', roles: ['Инициатор', 'Контроль', 'Подвижный'], complexity: 3 },
  hoodwink: { attr: 'Ловкость', roles: ['Контроль', 'Урон', 'Неуловимый'], complexity: 2 },
  treant: { attr: 'Сила', roles: ['Поддержка', 'Инициатор', 'Стойкий'], complexity: 1 },
}

export function hero(id: string): HeroView {
  const D = DB().data as unknown as { heroes: Record<string, { id: string; name: string; img: string }>; players: Record<string, { id: string; role: number | 'coach'; team: string }>
    heroStats: Record<string, { games: number; list: HS[] }>; playerStats: Record<string, { list: PS[] }>; teamStats: Record<string, Record<string, { picks: [string, number][]; bans: [string, number][] }>> }
  const h = D.heroes[id], st = D.heroStats['ti-2026'], list = st.list, s = list.find((x) => x.hero === id) ?? null
  const games = st.games, wr = s ? pct(s.pickWins, s.picks) : 0
  const meta: MetaRow[] = list.map((x) => ({ hero: x.hero, picks: x.picks, wr: pct(x.pickWins, x.picks), pb: x.pickBan, bans: x.bans }))
  const rk = (k: (x: MetaRow) => number, f: (x: MetaRow) => boolean = () => true) => { const l = meta.filter(f).sort((a, b) => k(b) - k(a)); const i = l.findIndex((x) => x.hero === id); return i < 0 ? 0 : i + 1 }
  const players: HeroPlayer[] = D.playerStats['ti-2026'].list.flatMap((p) => { const x = p.heroes.find((y) => y.hero === id); const pl = D.players[p.player]
    return x && pl ? [{ player: p.player, team: pl.team, pos: typeof pl.role === 'number' ? pl.role : 0, maps: x.maps, wins: x.wins }] : [] }).sort((a, b) => b.maps - a.maps || b.wins - a.wins)
  const teams: HeroTeam[] = Object.entries(D.teamStats['ti-2026']).map(([team, o]) => ({ team, picks: o.picks.find((y) => y[0] === id)?.[1] ?? 0, bans: o.bans.find((y) => y[0] === id)?.[1] ?? 0 }))
    .filter((x) => x.picks + x.bans).sort((a, b) => b.picks + b.bans - (a.picks + a.bans))
  const positions: Pos[] = [1, 2, 3, 4, 5].map((pos) => { const l = players.filter((p) => p.pos === pos); return { pos, maps: l.reduce((a, p) => a + p.maps, 0), wins: l.reduce((a, p) => a + p.wins, 0) } })
  // ‼️ пример: противостояния — из героев, что чаще всего встречаются на TI, со «сдвигом винрейта» ±
  const r = seed(id), pool = meta.filter((x) => x.hero !== id && x.picks >= 10).map((x) => x.hero)
  const pick = (n: number) => { const out: string[] = []; while (out.length < n && pool.length) { const k = pool.splice(Math.floor(r() * pool.length), 1)[0]; out.push(k) } return out }
  const best = pick(5).map((x, i) => ({ hero: x, d: +(4.8 - i * 0.8 - r() * 0.4).toFixed(1) }))
  const worst = pick(5).map((x, i) => ({ hero: x, d: -+(5.1 - i * 0.8 - r() * 0.4).toFixed(1) }))
  // ‼️ пример: противостояния со всеми героями, которых на TI брали от 5 раз — сдвиг ±6 %, линия ±12 %
  const r2 = seed(id + ':mu'), matchups = meta.filter((x) => x.hero !== id && x.picks >= 5).map((x) => ({ hero: x.hero, d: +((r2() - 0.5) * 11).toFixed(1), lane: +((r2() - 0.5) * 22).toFixed(1), games: Math.max(3, Math.round(x.picks * (0.15 + r2() * 0.3))) }))
  const patches = ['7.40c', '7.41', '7.41a', '7.41b', '7.41c', '7.41d'].map((p, i) => ({ p, wr: Math.round(44 + r() * 10 + i * 0.6), pick: Math.round(8 + r() * 14 + i) }))
  const ex = EX[id] ?? { attr: 'Универсал', roles: ['Урон'], complexity: 2 }
  return {
    id, name: h?.name ?? id, img: img(h?.img), ...ex, games, s,
    wr, pickRate: s ? pct(s.picks, games) : 0, banRate: s ? pct(s.bans, games) : 0,
    rank: { picks: rk((x) => x.picks), wr: rk((x) => x.wr, (x) => x.picks >= 10), bans: rk((x) => x.bans), pb: rk((x) => x.pb), of: meta.length },
    players, teams, positions, best, worst, matchups, patches, meta,
  }
}
export const heroName = (h: string) => (DB() as unknown as { hero: (x: string) => { name: string } | null }).hero(h)?.name ?? h
export const teamName = (id: string, k: 'name' | 'mid' | 'tag' = 'name') => (window.DB as unknown as { name: (x: string, k: string) => string }).name(id, k)
export { pct }
export const plural = (n: number, a: string, b: string, c: string) => { const m = n % 10, h = n % 100; return m === 1 && h !== 11 ? a : m >= 2 && m <= 4 && (h < 12 || h > 14) ? b : c }
export const sgn = (d: number) => (d > 0 ? '+' : '−') + Math.abs(d).toFixed(1).replace('.', ',')
/** Герои, у которых на TI 2026 есть статистика, — для них страница строится */
export const hasHero = (id: string) => !!(DB().data as unknown as { heroStats: Record<string, { list: HS[] }> }).heroStats['ti-2026']?.list.some((x) => x.hero === id)
/** Раскладка по рядам: иконка встаёт в первый ряд, где до соседа слева не меньше gap % — иконки не налезают */
export const lanes = <T,>(l: T[], x: (v: T) => number, gap: number) => { const rows: number[] = []
  return [...l].sort((a, b) => x(a) - x(b)).map((v) => { const p = x(v); let r = rows.findIndex((last) => p - last >= gap); if (r < 0) { rows.push(p); r = rows.length - 1 } else rows[r] = p; return { v, p, r } }) }
