/** Живая: клик по вкладке двигает подложку */
function Живая(p: HeaderProps) { const [v, set] = useState(p.value ?? SERIES_BY_STATE[p.state].cur); return <Header key={p.state + (p.case ?? '')} {...p} value={v} onChange={set} /> }
