type View = 'cal' | 'table'
export type ToursPageProps = { viewer?: Viewer; /** Куда ведут теги (v7, лаба entity-tags) */ entityHref?: EntityHref; tourHref?: (t: TourRow) => string | undefined; view?: View; initial?: string; /** Месяц нажимается целиком, без лишних подложек (лаба v17) */ whole?: boolean; /** Наш стиль (лаба v18–v20) */ ours?: 'a' | 'b' | 'c'; /** Без панели дня (лаба v21) */ noDay?: boolean; /** Лого в дне крупнее (лаба v22) */ big?: boolean; /** Лого в квадратах (лаба v23) */ sq?: boolean; /** Матчи при наведении (лаба v24) */ withMatches?: boolean; /** Матч в карточке нажимается (лаба v25) */ matchHref?: (m: RealMatch) => string | undefined; /** Главные турниры крупно сверху, как в концепте (лаба v26) */ featured?: boolean; /** Один виджет: вид «Календарь / Таблица» и общий фильтр — в шапке виджета (лаба v27) */ unified?: boolean; /** Шапка одна на оба вида: заголовок «Турниры Dota 2», без подсказок, числа и «Сбросить» — кнопки не прыгают (лаба v28) */ same?: boolean; /** Раскладка (лаба v29–v31): top — главные на всю ширину над колонками; full — без правой колонки */ layout?: 'top' | 'full'; /** Виджет без рамки и отступов — на всю ширину (лаба v32) */ flat?: boolean; /** События дня: наведение / шторка (лаба v33) */ byDay?: boolean; /** Карточка дня держится (лаба v34) */ hold?: boolean; /** Шторка дня как «О турнире» (лаба v35) */ phSheet?: boolean; /** Навигация месяца при одной шапке (лабы v36–v38) */ nav?: 'crumbs' | 'strip' | 'body' | 'crumbs2'; /** На телефоне вид и фильтр — строкой под заголовком (лаба v39) */ ctlBelow?: boolean; /** Разделитель крошек «/» (лаба v40) */ slash?: boolean; /** Пустые месяцы ужаты (лаба v41) */ tight?: boolean; /** Идущие с прошлого месяца (лаба v42) */ cont?: boolean }
const go = (href?: string) => { if (href) window.location.href = href }

/** Список турниров движка v6 — реальные турниры Dota 2 (Liquipedia) с цветными лого; календарь v9: год как HLTV, месяц плашками с лого. Две колонки, справа место под виджет. */
const NO_HREF: EntityHref = () => undefined

export function ToursPage({ viewer = 'in', tourHref, view: v0 = 'cal', initial, whole, ours, noDay, big, sq, withMatches, matchHref, featured, unified, same, layout, flat, byDay, hold, phSheet, nav, ctlBelow, slash, tight, cont, entityHref }: ToursPageProps) {
  const [rows, setRows] = useState<TourRow[] | null>(null)
  useEffect(() => { loadRealRows().then((r) => setRows(r.sort(byDefault))) }, [])
  const [mt, setMt] = useState<Record<string, RealMatch[]>>({})
  useEffect(() => { if (withMatches) loadRealMatches().then(setMt) }, [withMatches])
  const [view, setView] = useState<View>(v0)
  const open = (t: TourRow) => go(tourHref?.(t))
  const f = useTableFilter(TOUR_FIELDS, rows ?? [])
  const { ref, narrow } = useNarrow(640)
  const seg = <Segment<View> size="sm" value={view} onChange={setView} options={[{ value: 'cal', label: 'Календарь' }, { value: 'table', label: 'Таблица' }]} />
  const ctl = unified ? <>{seg}<TableFilter f={f} narrow={narrow} /></> : undefined
  const shown = unified ? f.rows : rows
  return (
    <EntityHrefProvider value={entityHref ?? NO_HREF}><CellTagsProvider>
    <div className={'etours' + (flat ? ' etours--flat' : '')}>
      <SiteHeader active="tournaments" viewer={viewer} />
      {layout === 'top' && featured && rows && <div className="etours__top"><Featured tours={rows} onOpen={open} /></div>}
      <main className="etours__cols">
        <div ref={ref} className="etours__l">
          {layout !== 'top' && featured && rows && <Featured tours={rows} onOpen={open} />}
          {!unified && <div className="etours__view">{seg}</div>}
          {!rows ? <Widget head="line" fluid title="Календарь"><EmptyState title="Загружаем турниры…" /></Widget>
            : !shown ? null : view === 'cal' ? <Calendar rows={shown} actions={ctl} title={same ? 'Турниры Dota 2' : undefined} onOpen={open} initial={initial} whole={whole} ours={ours} noDay={noDay} big={big} sq={sq} matches={withMatches ? mt : undefined} matchHref={matchHref} byDay={byDay} hold={hold} phSheet={phSheet} nav={nav} actionsBelow={ctlBelow} slash={slash} tight={tight} cont={cont} /> : <ToursTable rows={shown} onOpen={open} actions={ctl} filter={!unified} bare={same} actionsBelow={ctlBelow} />}
        </div>
        {layout !== 'full' && <aside className="etours__r"><Widget head="card" fluid title="Виджет"><EmptyState title="Пока пусто" hint="Здесь будет виджет правой колонки" /></Widget></aside>}
      </main>
    </div>
    </CellTagsProvider></EntityHrefProvider>
  )
}
