/** Страница игрока движка (концепт) — «Активность». Стоит на странице игрока v1. */
const meta: Meta<typeof PlayerActivity> = { title: 'Движок/Игрок/Активность/PlayerActivity v1', component: PlayerActivity, tags: ['concept'], parameters: { layout: 'fullscreen' },
  decorators: [(St) => <div className="eng-surface" style={{ padding: 20, width: 320 }}><St /></div>] }
export default meta
type S = StoryObj<typeof PlayerActivity>
export const Pro: S = { name: 'Про · Yatoro', render: () => <PlayerActivity p={player('pro')} /> }
