import { DB, img } from '@/data/db'

export type Who = 'pro' | 'pub'
export type MapRow = {
  key: string; date: string; t: number
  vs?: string; mode?: string; party?: number
  live?: string; win: boolean | null
  hero: string; k: number; d: number; a: number; gpm: number; xpm: number; dur: number
  stage?: string
}
export type HeroRow = { hero: string; name: string; maps: number; wins: number; k: number; d: number; a: number; gpm?: number }
