import { useState } from 'react'
import { allMatches, allTours, countOf, listOf, tierN, type GameId, type Tab } from '@/engine/schedule/data'
import { ScheduleBarV4 } from './ScheduleBar'

/** Полоса над расписанием — игры (фильтр), вкладки «Live · Скоро · Итоги» с числом, турниры карточками. Как на странице расписания движка. */
function Demo({ g0 = ['dota2'] as GameId[] }) {
  const [games, setGames] = useState<GameId[]>(g0), [tab, setTab] = useState<Tab>('soon'), [tour, setTour] = useState('all')
  const M = allMatches(), counts = { live: countOf(M, 'live', 'ok'), soon: countOf(M, 'soon', 'ok'), done: countOf(M, 'done', 'ok') }
  const tours = allTours().map((t) => ({ ...t, n: listOf(M.filter((m) => m.tour === t.id), tab, 'ok').length })).filter((t) => t.n > 0 || (tab === 'soon' && t.state !== 'done'))
    .sort((a, b) => (+(b.state === 'live') - +(a.state === 'live')) || tierN(a) - tierN(b) || a.from.localeCompare(b.from))
  return <ScheduleBarV4 games={games} onGames={setGames} tab={tab} counts={counts} onTab={setTab} tours={tours} more={0} tour={tour} onTour={setTour} total={countOf(M, tab, 'ok')} />
}
const meta: Meta = { title: 'Движок/Расписание/Полоса фильтров/ScheduleBar v4', parameters: { layout: 'fullscreen' } }
export default meta
export const Dota2: StoryObj = { name: 'Dota 2', render: () => <Demo /> }
export const ВсеИгры: StoryObj = { name: 'Все игры', render: () => <Demo g0={[]} /> }
