/** Страница команды движка — ‼️ концепт (лаба team-page v36, дирижёр 23.11). Плитки внизу главной колонки: винрейт карт кольцом, серии полосками, средняя длительность, пул героев, лучший KDA, «визитка» — самый частый герой, похожий драфт. */
export function TeamTiles({ t }: TeamTilesProps) {
  const [mw, ml] = t.totals.maps, star = [...players(t)].sort((a, b) => (b.kda ?? 0) - (a.kda ?? 0))[0], sig = t.heroAgg[0], twin = t.similar[0]
  return (
    <div className="tm-tiles">
      <div className="tm-tile"><small>Винрейт карт</small><Ring v={pct(mw, mw + ml)} size={56} /><em>{mw}–{ml}</em></div>
      <div className="tm-tile"><small>Серии</small><div className="tm-tile__ser">{t.series.slice().reverse().map((s) => <i key={s.id} className={s.win === null ? 'is-live' : s.win ? 'is-w' : 'is-l'} />)}</div><em>{t.totals.series.join('–')}</em></div>
      <div className="tm-tile"><small>Ср. длительность</small><b>{mmss(t.avgDur)}</b><em>за карту</em></div>
      <div className="tm-tile"><small>Пул героев</small><div className="tm-tile__stack">{t.heroAgg.slice(0, 6).map((h) => <HeroIcon key={h.hero} hero={h.hero} size={22} />)}</div><em>{t.pool} героев</em></div>
      {star && <div className="tm-tile"><small>Лучший KDA</small><EntityTag kind="player" id={star.id} size="m" plain /><em>{f1(star.kda)}</em></div>}
      {sig && <div className="tm-tile"><small>Визитка</small><HeroIcon hero={sig.hero} size={36} /><em>{sig.maps} карт · {pct(sig.wins, sig.maps)}%</em></div>}
      {twin && <div className="tm-tile tm-tile--wide"><small>Похожий драфт</small><EntityTag kind="team" id={twin.id} size="m" /><em>{twin.sim}%</em></div>}
    </div>)
}
