  const months = useMemo(() => Array.from({ length: 12 }, (_, i) => { const d = new Date(Date.UTC(y0, 7 + i, 1)), y = d.getUTCFullYear(), m = d.getUTCMonth(), a = dn(d.toISOString()), len = new Date(Date.UTC(y, m + 1, 0)).getUTCDate(), k = d.toISOString().slice(0, 7)
    return { k, y, m, a, len, L: rows.filter((t) => t.from.slice(0, 7) === k).sort((p, q) => p.tier - q.tier || p.from.localeCompare(q.from)) } }), [rows, y0])
