export type TourCardProps = { tour: TourRow; onOpen?: (t: TourRow) => void; onClose?: () => void }

/** Карточка турнира по клику в календаре (голосовое 16.11, 41-27: «при клике — тир и состав участников, дальше провалиться в турнир»).
 *  Шапка: лого, название, тир, статус · даты. Ниже: стадии (если есть в базе), участники лого с наведением, составы %, место и призовые. Внизу — «Открыть турнир». */
export function TourCard({ tour: t, onOpen, onClose }: TourCardProps) {
  const year = t.to.slice(0, 4)
  return (
    <div className="etcard">
      <header className="etcard__h">
        {t.logo ? <img className="etcard__lg" src={img(t.logo)} alt="" /> : <span className="etcard__lg etcard__lg--0" aria-hidden="true">{initials(t.name)}</span>}
        <span className="etcard__t">
          <TierTag tier={t.tier} size="sm" />
          <b className="etcard__n">{t.name}</b>
          <span className="etcard__s">{t.state === 'live' && <i className="etcard__dot" />}{STATE_LABEL[t.state]}{t.stage ? ' · ' + t.stage : ''} · <span className="num">{dm(t.from)} – {dm(t.to)}.{year}</span></span>
        </span>
        {onClose && <Button variant="ghost" size="xs" aria-label="Закрыть" onClick={onClose} icon="close" />}
      </header>
      {t.stages.length > 0 && (
        <ol className="etcard__stg">
          {t.stages.map((s) => <li key={s.name}><span>{s.name}</span><span className="num">{dm(s.from)}{s.to !== s.from ? ' – ' + dm(s.to) : ''}</span></li>)}
        </ol>
      )}
      <section className="etcard__sec">
        <div className="etcard__row"><span>Участники</span><b className="num">{t.teams.length || '—'}</b><span className="etcard__sp" /><span>Составы</span><b className="num">{t.rosters == null ? '—' : t.rosters + '%'}</b></div>
        {t.teams.length ? (
          <div className="etcard__teams">{t.teams.map((id) => <Tooltip key={id} content={teamName(id)}><span className="etcard__team" tabIndex={0}><TeamLogo team={id} size={24} alt={teamName(id)} /></span></Tooltip>)}</div>
        ) : <p className="etcard__none">Участников ещё не объявили</p>}
      </section>
      <dl className="etcard__kv">
        <div><dt>Место</dt><dd>{t.where ? t.where.filter(Boolean).join(' · ') : '—'}</dd></div>
        <div><dt>Призовые</dt><dd className="num">{t.prize ? usd(t.prize) : '—'}</dd></div>
      </dl>
      {t.page
        ? <Button variant="primary" size="sm" className="etcard__go" onClick={() => onOpen?.(t)}>Открыть турнир<Icon name="arrow-right" /></Button>
        : <p className="etcard__none">Страницы турнира в движке пока нет</p>}
    </div>
  )
}
