const meta: Meta<typeof Mvp> = { title: 'Сайт/Матч/MVP матча/Mvp v2', component: Mvp, parameters: { layout: 'padded' }, args: { state: 'post', viewer: 'in', tab: 0 },
  argTypes: { state: { ...stateArg(), description: 'Состояние матча: виджет есть только после матча (post), в остальных — нет' }, viewer: viewerArg, tab: { control: { type: 'inline-radio' }, options: [0, 1], description: 'Открытый вид сегмента: 0 — «Матч», 1 — «Турнир»' }, ...statusArgTypes } }
export default meta
type S = StoryObj<typeof Mvp>

export const Матч: S = { name: 'После матча · «Матч»' }
export const Турнир: S = { name: '«Турнир» — в твоём составе', args: { tab: 1 } }
export const Гость: S = { name: 'Гость · «Матч»', args: { viewer: 'guest' } }
