    const tr = el.getBoundingClientRect(), left = Math.min(Math.max(8, t.r.left), innerWidth - tr.width - 8), top = t.r.top - tr.height - 6 < 8 ? t.r.bottom + 6 : t.r.top - tr.height - 6
