/** «Эта серия» — считаем из GS_DATA, как лаба (w-stats-2/_wsg.js: md, mirror + WSG_LM 'mini', WSG_PNICK; w-lanemap/_lm.js: lanes, SPOT):
 *  сыгранные карты — пики с ником и нетворсом на конец, золото команд на конец и полоса; идущая (до секунды состояния) — без чисел.
 *  Мини-карта линий: линия — lane_role игрока, позиция — по деньгам (maps.ts), перевес линии — разница нетворса к 10′. */
const nwT = (p: GsPlayer, t: number) => { const a = p.nw_t || []; return a.length ? a[Math.max(0, Math.min(a.length - 1, Math.floor(t / 60)))] || 0 : p.net_worth || 0 }
const kLane = (v: number) => (Math.abs(v) / 1000).toFixed(1).replace('.', ',') + 'k'
const ROLE = ['', 'Керри', 'Мид', 'Оффлейн', 'Поз. 4', 'Поз. 5']
type Lane = 'top' | 'mid' | 'bot'
const SPOT: Record<Lane, Record<'r' | 'd', [number, number][]>> = { top: { r: [[.13, .42], [.24, .42]], d: [[.24, .16], [.35, .16]] }, mid: { r: [[.43, .57]], d: [[.56, .46]] }, bot: { r: [[.56, .81], [.68, .81]], d: [[.75, .57], [.86, .57]] } }
const LBL: Record<Lane, [number, number]> = { top: [.2, .29], mid: [.62, .63], bot: [.8, .7] }
const pc = (v: number) => +(v * 100).toFixed(1)
const sp = (S: [number, number][], i: number): [number, number] => S[i] || [S[S.length - 1][0] + .11 * (i - S.length + 1), S[S.length - 1][1]]
const gsHero = (od: number) => window.GS_DATA.heroes[od]
