import type { NewsRowProps } from '../NewsRow'
import type { MatchColumn } from '../MatchColumns'
import { logoOf, newsData, type Match, type NewsItem, type Part } from './news'

export const rowOf = (n: NewsItem): NewsRowProps => { const d = newsData()
  return { href: n.url, time: n.fresh ? 'сейчас' : d.when2(n), tier1: n.tour === 'uni', fresh: n.fresh, parts: d.mark(n.title) } }

/** Фильтр ленты: матч или тема (выбор один) */
export type NewsFilter = { match?: string | null; topic?: string | null }
export const filterFn = (f: NewsFilter) => { const d = newsData(), m = f.match ? d.MM.find((x) => x.id === f.match) : null, t = f.topic ? d.TOPICS.find((x) => x.id === f.topic) : null
  return (n: NewsItem) => (m ? d.inM(m)(n) : t ? t.t(n) : true) }

/** Три колонки матча: обе команды · первая · вторая — свежие сверху, по 6 */
export const matchColumns = (m: Match): MatchColumn[] => { const d = newsData(), has = (id: string) => (n: NewsItem) => d.nb(n).teams.includes(id), L = d.tm(d.F.filter(d.inM(m)))
  const cols: [string, string[], NewsItem[]][] = [
    ['Обе команды', [logoOf(m.a), logoOf(m.b)], L.filter((n) => has(m.a)(n) && has(m.b)(n))],
    [d.teamName(m.a, 'mid'), [logoOf(m.a)], L.filter((n) => has(m.a)(n) && !has(m.b)(n))],
    [d.teamName(m.b, 'mid'), [logoOf(m.b)], L.filter((n) => has(m.b)(n) && !has(m.a)(n))]]
  return cols.map(([title, logos, l]) => ({ title, logos, count: l.length, items: l.slice(0, 6).map(rowOf) })) }
export const matchColumnsUsed = (m: Match) => { const d = newsData(), has = (id: string) => (n: NewsItem) => d.nb(n).teams.includes(id), L = d.tm(d.F.filter(d.inM(m)))
  return new Set([L.filter((n) => has(m.a)(n) && has(m.b)(n)).slice(0, 6), L.filter((n) => has(m.a)(n) && !has(m.b)(n)).slice(0, 6), L.filter((n) => has(m.b)(n) && !has(m.a)(n)).slice(0, 6)].flat()) }

/** «Главное»: слайдер — 5 самых читаемых с фото; первая колонка — 5 следующих; справа 2 средние с фото */
export type TopItem = { href: string; img: string; time: string; tier1: boolean; title: string; parts: Part[]; lede?: string }
export const topBlock = (f: NewsFilter) => { const d = newsData(), L = d.sc(d.F.filter(filterFn(f))), main = L.filter((n) => n.img).slice(0, 5), rest = L.filter((n) => !main.includes(n))
  const list = rest.slice(0, 5), meds = rest.filter((n) => n.img && !list.includes(n)).slice(0, 2)
  const ti = (n: NewsItem): TopItem => ({ href: n.url, img: n.img, time: d.when2(n), tier1: n.tour === 'uni', title: n.title, parts: d.mark(n.title), lede: n.lede || undefined })
  return { list: list.map(rowOf), main: main.map(ti), meds: meds.map(ti), used: new Set([...list, ...meds]) } }

/** Лента ниже: карточки по дням, свежие сверху; видно N, дальше — «Показать ещё 16 из M» */
export type FeedCardData = { href: string; cover: { img: string } | { logos: string[] }; time: string; tier1: boolean; parts: Part[] }
export type FeedDay = { title: string; count: number; cards: FeedCardData[] }
export const feed = (f: NewsFilter, used: Set<NewsItem>, n = 16) => { const d = newsData(), L = d.tm(d.F.filter((x) => filterFn(f)(x) && !used.has(x))), S = L.slice(0, n)
  const days: FeedDay[] = [...new Set(S.map((x) => x.t.slice(0, 10)))].map((day) => ({ title: d.dayName(day), count: L.filter((x) => x.t.startsWith(day)).length,
    cards: S.filter((x) => x.t.startsWith(day)).map((x) => ({ href: x.url, cover: d.cover(x), time: x.t.slice(11, 16), tier1: d.isTier1(x), parts: d.chips(x) })) }))
  return { days, rest: L.length - n, more: Math.min(16, L.length - n) } }
