const TeamCell = ({ team }: { team: string }) => <span className="tgs__tm"><Logo team={team} size={20} /><span>{team}</span></span>

/** Групповой этап (лаба gs-tournament/_ours.js, v46).
 *  Universe — две группы, на группу одна таблица: место, команда, клетки против каждого соперника тепловой картой (2:0 ярко, 2:1 бледно, ничья серо; дата — подсказкой), серии «победы–ничьи–поражения», карты с разницей; 2 лучших — зелёным местом.
 *  TI — швейцарка: место, команда, матчи по порядку (лого соперника + счёт тем же цветом), серии, карты, итог этапа. */
