const meta: Meta<typeof HeroStats> = { title: 'Сайт/Турнир/Статистика героев/HeroStats v2', tags: ['deprecated'], component: HeroStats, parameters: { layout: 'fullscreen' }, decorators: [(St) => <div style={{ padding: 20 }}><div style={{ width: 1016 }}><St /></div></div>],
  argTypes: { tour, status, onRetry,
    sort: { control: 'select', options: ['n', 'p', 'pv', 'pwr', 'pt', 'r', 'rv', 'rwr', 'd', 'dv', 'dwr', 'b', 'bt', 'pb', 'pbt'], description: 'Колонка сортировки при открытии: n — герой, p* — пики, r* — Radiant, d* — Dire, b* — баны, pb* — пик + бан (по умолчанию pb)' },
    dir: { control: 'inline-radio', options: [-1, 1], description: 'Направление: −1 — по убыванию (по умолчанию), 1 — по возрастанию' } } }
export default meta
type S = StoryObj<typeof HeroStats>
export const Universe: S = { name: 'Universe Ep. 7', args: { tour: 'ep7' } }
export const TI: S = { name: 'TI 2026', args: { tour: 'ti' } }
export const ПоПикам: S = { name: 'Сортировка: пики', args: { tour: 'ep7', sort: 'p' } }
export const ПоИмени: S = { name: 'Сортировка: герой А–Я', args: { tour: 'ep7', sort: 'n', dir: 1 } }
