function applyGroupCases(groups: Group[], c?: TourCases): Group[] {
  if (!c) return groups
  return groups.map((g) => {
    let rows = g.rows.map((r) => ({ ...r, vs: { ...r.vs }, ff: { ...r.ff }, re: { ...r.re } }))
    for (const r of c.rematch ?? []) { const a = teamName(r.a), b = teamName(r.b)
      for (const row of rows) { if (row.team === a && b in row.vs) row.re![b] = r.note; if (row.team === b && a in row.vs) row.re![a] = r.note } }
    for (const o of c.out ?? []) {
      const t = teamName(o.team), row = rows.find((r) => r.team === t); if (!row) continue
      // расписание известно заранее: матчи по порядку дней; после after сыгранных — все оставшиеся тех
      const order = Object.entries(row.vs).filter(([, v]) => v).sort((x, y) => x[1]![2] - y[1]![2]).map(([k]) => k)
      for (const opp of order.slice(o.after)) { row.ff![opp] = true; const or = rows.find((r) => r.team === opp); if (or) or.ff![t] = true }
      row.out = true
      rows = [...rows.filter((r) => r !== row), row]
    }
    return { ...g, rows }
  })
}
